<section class="hero compact"><div><span class="eyebrow">AGENDA SURAT KELUAR</span><h1>Daftar Record Nomor</h1><p>Nomor yang dibatalkan tetap tersimpan dan tidak digunakan ulang.</p></div><a class="btn primary" href="/letters/create">+ Generate Nomor</a></section>
<section class="card"><form method="get" class="filters"><label>Cari<input name="q" value="<?=e($filters['q'])?>" placeholder="Nomor / tujuan / perihal"></label><label>Tim<select name="team"><option value="">Semua</option><?php foreach($teams as $t):?><option value="<?=$t['id']?>" <?=((string)$filters['team']===(string)$t['id'])?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select></label><label>Sifat<select name="sensitivity"><option value="">Semua</option><?php foreach($sensitivities as $s):?><option value="<?=e($s['code'])?>" <?=$filters['sensitivity']===$s['code']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">Semua</option><option value="ACTIVE" <?=$filters['status']==='ACTIVE'?'selected':''?>>Aktif</option><option value="CANCELLED" <?=$filters['status']==='CANCELLED'?'selected':''?>>Dibatalkan</option></select></label><label>Tahun<input name="year" inputmode="numeric" value="<?=e($filters['year'])?>"></label><button class="btn primary" type="submit">Terapkan</button><a class="btn ghost" href="/letters">Reset</a></form></section>
<section class="card"><div class="section-title"><div><span class="eyebrow">HASIL</span><h2><?=count($letters)?> record</h2></div></div><div class="table-wrap"><table><thead><tr><th>No.</th><th>Nomor Surat</th><th>Jenis</th><th>Tim</th><th>Tujuan / Perihal</th><th>Sifat</th><th>Status</th><th>Pengaju</th></tr></thead><tbody><?php foreach($letters as $r):?><tr><td><?=e($r['agenda_number'])?></td><td><a class="code" href="/letters/<?=$r['id']?>"><?=e($r['letter_number'])?></a></td><td><?=e($r['letter_type_name'])?></td><td><?=e($r['work_team_name'])?></td><td><b><?=e($r['recipient'])?></b><small><?=e($r['subject'])?></small></td><td><?=e(sensitivity_label($r['sensitivity']))?></td><td><span class="badge <?=strtolower($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['requester_name'])?></td></tr><?php endforeach;?></tbody></table></div></section>
